import java.util.ArrayList;
import java.util.List;

public class MyClass {
    public void checkList(List<String> list) {
        if (list.size() == 0) {
            System.out.println("List is empty.");
        }
    }
}

afterExample:
import java.util.ArrayList;
import java.util.List;

public class MyClass {
    public void checkList(List<String> list) {
        if (list.isEmpty()) {
            System.out.println("List is empty.");
        }
    }
}

